// Repositories/ClockEntryRepository.cs -- the real implementation
public IEnumerable<ClockEntry> GetEmployeeClockEntries(int employeeId, DateTime startDate, DateTime endDate)
{
    return _clockEntries.Where(entry =>
        entry.EmployeeId == employeeId &&
        entry.ClockOut != null &&
        entry.ClockIn >= startDate &&
        entry.ClockIn <= endDate);
}

// Services/PayrollService.cs -- the real implementation
public double CalculateTotalHours(int employeeId, DateTime startDate, DateTime endDate)
{
    var clockEntries = _clockEntryRepository.GetEmployeeClockEntries(employeeId, startDate, endDate);
    return clockEntries.Sum(x => x.GetDuartion().TotalHours);
}
